const segredo = (nome, no) => { try { return ($(no).all().find(i => i.json.chave === nome) || {}).json?.valor || ''; } catch (e) { return ''; } };
const fpLimpo = v => { const f = limpaId(v); return f.length >= 8 ? f : ''; };
const nomeOp = (op, mod) => { op = limpaTxt(op).slice(0, 15); const m = String(mod || '').toUpperCase(); return op ? op + (m === 'PRE' ? ' Pré-pago' : m === 'POS' ? ' Pós-pago' : '') : 'operadora não informada'; };

const email = limpaEmail(P.email), dia = String(P.data_compra || '').trim();
const vazio = (m) => [{ json: { ok: false, motivo: m, resposta: { success: false, enviado_para: email } } }];
if (!email.includes('@') || dia.length < 10) return vazio('dados incompletos');
const pags = linhas('Recuperar: ler pagamentos');
const tipos = ['venda', 'renovacao'];
const achados = pags.filter(x => String(x.email || '').trim().toLowerCase() === email && String(x.data_criacao || '').includes(dia) && tipos.includes(String(x.tipo || '').trim().toLowerCase())
 );
const alvo = achados[achados.length - 1];
if (!alvo) return vazio('compra nao encontrada');
const usuario = limpaUser(alvo.usuario_entregue);
const vendas = $('Recuperar: vendas da Liss').all().map(i => i.json);
const token = segredo('painel_token_publico', 'Recuperar: segredos');
const valida = s => s && !String(s).startsWith('(');
// candidatos: a propria linha e depois a compra original desse usuario (para renovacao, a senha e a da compra)
const cands = [alvo].concat(pags.filter(x => usuario && limpaUser(x.usuario_entregue) === usuario && x !== alvo).reverse());
let user = '', senha = '', log = [];
for (const c of cands) {
  if (String(c.plan_id || '').trim().toLowerCase() === 'liss') {
    const v = vendas.find(x => x.ref && x.ref === String(c.ref || '').trim()) || vendas.find(x => usuario && x.usuario === usuario && valida(x.senha));
    if (v && valida(v.senha)) { user = v.usuario; senha = v.senha; log.push('liss ' + v.ref); break; }
  } else if (token && /^[0-9]+$/.test(String(c.payment_id || '').trim())) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://painel.netliss.shop/api/public/payment/' + String(c.payment_id).trim() + '/status',
        headers: { 'X-Public-Api-Token': token }, json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
      const a = (r.body && (r.body.account || (r.body.data && r.body.data.account))) || {};
      if (a.username && valida(a.password)) { user = a.username; senha = a.password; log.push('painel ' + c.payment_id); break; }
      log.push('painel sem conta ' + c.payment_id + ' http ' + r.statusCode);
    } catch (e) { log.push('erro painel ' + e.message); }
  }
}
if (!user && usuario) { const v = vendas.find(x => x.usuario === usuario && valida(x.senha)); if (v) { user = v.usuario; senha = v.senha; } }
if (!user) return vazio('senha nao localizada: ' + log.join('; '));
let expira_br = '';
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://painel.netliss.shop/api/public/renewal/search', headers: { 'X-Public-Api-Token': token },
    body: { identifier: user }, json: true, timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const a = (r.body && r.body.data && r.body.data.account) || {};
  if (a.expires_at) { const d = new Date(String(a.expires_at).replace(' ', 'T') + (String(a.expires_at).includes('Z') ? '' : '-03:00')); expira_br = isNaN(d) ? String(a.expires_at) : d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }).replace(',', '').slice(0, 16); }
} catch (e) {}
return [{ json: { ok: true, email, usuario: user, senha, expira_br: expira_br || 'consulte no aplicativo', tipo: alvo.tipo, log, resposta: { success: true, enviado_para: email } } }];

